/* C ref: pline.c vpline() -> vsnprintf.  js/display.js:3124 pline(msg) takes a
 * SINGLE string, so `pline("%s ...", arg)` prints the literal "%s".  This is
 * the minimal C-compatible conversion set actually used by the pline_The call
 * sites in this file; unknown specifiers are left verbatim, which is what a
 * mismatched vsnprintf would do rather than dropping text. */
/* Exported so js/do_wear.js's You()/Your()/yname() share THIS body rather than
 * growing a fourth private formatter — js/potion.js and js/read.js each already
 * carry their own, and js/read.js:2307's `pline("Your " + fmt, ...args)` drops
 * the varargs entirely, printing "%s" to the topline verbatim. */
export function _plineVFmt(fmt, args) {
    let i = 0;
    return String(fmt).replace(/%(?:%|l?[sdcui])/g, (spec) => {
        if (spec === '%%') return '%';
        const a = args[i++];
        if (spec.endsWith('c'))
            return typeof a === 'number' ? String.fromCharCode(a) : String(a);
        if (spec.endsWith('s'))
            return a == null ? '' : String(a);
        /* C's %d/%u are int (wraps at 32 bits, which `| 0` reproduces); %ld/%lu
         * are long and must NOT wrap — `Your("%ld gold pieces...", umoney)`
         * (js/vault.js:91) is the case that would print a negative purse. */
        return spec.length === 3 ? String(Math.trunc(Number(a)) || 0) : String(a | 0);
    });
}

/* C ref: pline.c:427-434 You(line, ...) —
 *   vpline(YouMessage(tmp, "You ", line), the_args) — a literal "You " prefix. */
async function _goto_level_You(fmt, ...args) {
    return pline('You ' + _plineVFmt(fmt, args));
}

/* C ref: you.h:240 #define Role_if(X) (gu.urole.mnum == (X))
 * C ref: you.h:290 #define Race_if(X) (gu.urace.mnum == (X))
 * Race_if was a throw-stub (see its old body, removed below); it sits in the
 * same `||` expression as Role_if at the touchstone check, so binding Role_if
 * alone would only have moved the abort one operand to the right. */
function Role_if(pm) {
    return ((game.urole && game.urole.mnum) | 0) === (pm | 0);
}

/* C ref: mondata.h:135 #define type_is_pname(ptr) (((ptr)->mflags2 & M2_PNAME) != 0L)
 * Mirrors js/mcastu.js:793, which carries the identical body. */
const _M2_PNAME = 0x00080000; /* C ref: monflag.h:141 M2_PNAME 0x00080000L.
                               * Agrees with js/mcastu.js:787, js/makemon.js:153,
                               * js/mhitm.js:258, js/objnam.js:2618,
                               * js/questpgr.js:28 and js/cmd.js:9270. */
function type_is_pname(ptr) {
    return !!ptr && ((ptr.mflags2 | 0) & _M2_PNAME) !== 0;
}

