//   dagger(a,uwep,quan=1) → DOWNPLAY (not in prompt)
//   bow(b,uquiver): WEAPON_CLASS → SUGGEST → "b"
//   arrows(c): WEAPON_CLASS → SUGGEST → "c"
//   arrows(d): WEAPON_CLASS → SUGGEST → "d"
//   prompt: "What do you want to throw? [bcd or ?*]" (39 chars)
//
// After 'd' selected: "In what direction?" prompt (19 chars) via getdir.
// throwit: ammo without matching launcher → "You aren't wielding a bow,
//   so you throw your arrow by hand." message.
/* C cmd.c:get_count. Command counts are C long (LP64 in the target build),
 * so arithmetic stays in BigInt. Callers with LARGEST_INT bounds may convert
 * the result to Number. `count.value` is the C output pointer; `count.echo`
 * retains the windowport's last painted count for existing getobj callers. */
export async function get_count(allowchars, inkey, maxcount, count, gc_flags) {
    const g = game;
    let key;
    const save_input_state = g.program_state.input_state;
    let cnt = 0n;
    const first = inkey ? BigInt(inkey - 48) : 0n;
    const maximum = BigInt(maxcount), LONG_MAX = 9223372036854775807n;
    let backspaced = false, showzero = true;
    const historicmsg = !!(gc_flags & GC_SAVEHIST);
    const conditionalmsg = !!(gc_flags & GC_CONDHIST);
    const echoalways = !!(gc_flags & GC_ECHOFIRST);
    const saved_history = g._topl_suppress_history;

    count.value = 0n;
    count.echo = null;
    try {
        for (;;) {
            if (inkey) {
                key = inkey;
                inkey = 0;
            } else {
                g.program_state.input_state = save_input_state;
                key = await readchar();
            }
            if (key >= 48 && key <= 57) {
                const dgt = BigInt(key - 48);
                // integer.h:AppendLongDigit returns -1 on overflow; get_count
                // resets that to zero before applying its positive maximum.
                cnt = cnt < LONG_MAX / 10n
                    || (cnt === LONG_MAX / 10n && dgt <= LONG_MAX % 10n)
                    ? cnt * 10n + dgt : -1n;
                if (cnt < 0n) cnt = 0n;
                else if (maximum > 0n && cnt > maximum) cnt = maximum;
                showzero = (key === 48);
            } else if (key === 8 || key === 127) {
                if (!cnt && !echoalways) break;
                showzero = false;
                cnt /= 10n;
                backspaced = true;
            } else if (key === g.Cmd.spkeys[NHKF_ESC]) {
                break;
            } else if (allowchars === null || key === 0
                       || allowchars.includes(String.fromCharCode(key & 0xff))) {
                count.value = cnt;
                if (BigInt(count.value) !== cnt)
                    throw new Error('get_count: cmdcount_nht');
                break;
            }
            if (cnt > 9n || backspaced || echoalways) {
                const qbuf = (backspaced && !cnt && !showzero)
                    ? 'Count: ' : `Count: ${cnt}`;
                if (!(backspaced && !cnt && !showzero)) backspaced = false;
                // Current windowport spelling of clear_nhwindow(WIN_MESSAGE),
                // custompline(SUPPRESS_HISTORY) and mark_synch(). The last echo
                // is display bookkeeping, not an extra command-count value.
                g._pending_message = '';
                g._resultMessage = null;
                g._topl_suppress_history = true;
                await pline(qbuf);
                await flush_screen(1);
                set_cursor(qbuf.length, 0);
                count.echo = qbuf;
            }
        }
        if (historicmsg || (conditionalmsg && BigInt(count.value) !== first))
            putmsghistory(`Count: ${count.value} ${key2txt(key & 0xff)}`, false);
        return (key << 24) >> 24;
    } finally {
        g._topl_suppress_history = saved_history;
    }
}

export async function getobj_get_count(inkey) {
    const count = { value: 0n, echo: null };
    const key = await get_count(null, inkey, LARGEST_INT, count, GC_SAVEHIST);
    return { key, count: Number(count.value), echo: count.echo };
}

/* C cmd.c:parse. Keep the assignment to last_command_count before the
 * repeat/previous-message/named-command tests, exactly as in the C source. */
async function parse() {
    const g = game;
    let foo, bind;
    g.iflags.in_parse = true;
    g.command_count = 0;
    g.context.move = true;
    await flush_screen(1);
    /* The arrival pages raised by this flush (do.c:1849+ messages) are the last
     * the painted tutorial hero outlives: bot() repaints the live hero after. */
    if (g._tutorialStatusOverride) {
        g._tutorialStatusOverride = null;
        rebuild_screen_output();
    }
    g.program_state.input_state = 1; // commandInp

    if (!g.Cmd.num_pad || (foo = await readchar()) === g.Cmd.spkeys[NHKF_COUNT]) {
        g.program_state.input_state = 1;
        const count = { value: 0n };
        foo = await get_count(null, 0, LARGEST_INT, count, GC_NOFLAGS);
        g.command_count = Number(count.value); // bounded by LARGEST_INT
    }
    g.last_command_count = g.command_count;
    if (foo === g.Cmd.spkeys[NHKF_ESC]) {
        g._pending_message = '';
        g.command_count = 0;
        g.last_command_count = 0;
    } else if (g.gi?.in_doagain) {
        g.command_count = g.last_command_count;
    } else if (foo && (bind = cmdbind_get(foo & 0xff))
               && bind.cmd && ['do_repeat', 'doprev_message', 'doextcmd'].includes(bind.cmd.func)) {
        g.command_count = g.last_command_count;
    }
    g.multi = g.command_count;
    if (g.multi) g.multi--;
    g.cmd_key = foo;
    g._pending_message = '';
    /* C parse() clear_nhwindow(WIN_MESSAGE): a non-EMPTY topline is erased
     * (wintty.c tty_clear_nhwindow).  tty_nhgetch's reset (js/input.js) does
     * this normally; the fuzzer's readchar never reaches it. */
    if (g._topl_sticky !== g._topl_empty_sticky)
        g._topl_sticky = null;
    g.iflags.in_parse = false;
    return g.cmd_key;
}






