        const pageStart = pageIdx * PAGE_CONTENT;
        const pageLines = content.slice(pageStart, pageStart + PAGE_CONTENT);
        pageSelectable = new Set(
            contentItems.slice(pageStart, pageStart + PAGE_CONTENT)
                .filter(Boolean).map((it) => it.invlet | 0));
