        const kmax = NODIAG(u.umonnum) ? (N_DIRS / 2) : N_DIRS;
        /* C cmd.c: dirs_ord[] maps the rn2 index into the 8-way direction
         * order; xdir/ydir then give the offsets.  Use the C dirs_ord ordering. */
        const dirs_ord = [0, 2, 4, 6, 1, 3, 5, 7]; /* cmd.c dirs_ord[] */
        const k = dirs_ord[rn2(kmax)] | 0;
