            let i = 79;
            if (str.length > 79)
                while (i && str[i] !== ' ' && str[i] !== '\n') i--;
            if (str.length <= 79 || !i) { _putLines.push(str); break; }
            _putLines.push(str.slice(0, i));
            str = str.slice(i + 1);
