    const _offx0 = 80 - _maxcol - 1 <= 0;
    const windowLines = [..._putLines, _offx0 ? ' --More--' : '--More--'];
    /* wintty.c:1924 `cw->maxrow >= rows` -> offx 0, cleared screen, 23-line
     * pages: the same fullscreen pager look-window.js implements. */
