/* C include/obj.h:418
 *   #define is_flimsy(otmp)                           \
 *       (objects[(otmp)->otyp].oc_material <= LEATHER \
 *        || (otmp)->otyp == RUBBER_HOSE)
 * objclass.h:20 LEATHER == 7, so "flimsy" is LIQUID/WAX/VEGGY/FLESH/PAPER/
 * CLOTH/LEATHER (and the rubber hose), i.e. soft MATERIALS -- it has nothing
 * to do with projectiles.  This carried a seven-otyp list of arrows/bolts/
 * darts under the caption "a breakable projectile", which is wrong in BOTH
 * directions: every one of those otyps is IRON (11) and therefore NOT flimsy
 * to C, while every food, scroll, cloth and leather item C calls flimsy read
 * false here.  Same body as js/polyself.js:867, js/do_wear.js:1910 and
 * js/trap.js:2053 _mdw_is_flimsy, which all already had it right. */
const _FLIMSY_LEATHER = 7;      /* objclass.h:20 LEATHER */
const _FLIMSY_RUBBER_HOSE = 78; /* objects.h RUBBER_HOSE (JS otyp) */
function is_flimsy(obj) {
    if (!obj) return false;
    const t = obj.otyp | 0;
    return (MKOBJ_OC_MATERIAL[t] | 0) <= _FLIMSY_LEATHER || t === _FLIMSY_RUBBER_HOSE;
}





