/* C ref: hack.c:4156-4206 saving_grace(int dmg)
 * Once per game, if receiving a killing blow from above 90% HP,
 * allow the hero to survive with 1 HP. */
export function saving_grace(dmg) {
    const g = game;

    /* negative damage shouldn't happen, but reject it if it does */
    if (dmg < 0) {
        impossible_cmd('saving_grace check for negative damage? (%d)', dmg);
        return 0;
    }

    /* saving grace doesn't protect you from your own actions */
    if (!g.context || !g.context.mon_moving) {
        return dmg;
    }

    /* no need for saving grace if damage won't kill */
    if (dmg < g.u.uhp || g.u.uhp <= 0) {
        return dmg;
    }

    /* already triggered this turn; just cap damage */
    if (g.gs && g.gs.saving_grace_turn) {
        return g.u.uhp - 1;
    }

    /* trigger if: haven't used it yet AND were at 90%+ HP at turn start */
    if (!g.u.usaving_grace &&
        (g.gu.uhp_at_start_of_monster_turn * 100 / g.u.uhpmax) >= 90) {

        livelog_printf(LL_CONDUCT | LL_SPOILER, "%s (%d damage, %d/%d HP)",
                       "survived one-shot death via saving-grace",
                       /* include damage that happened earlier this turn */
                       g.gu.uhp_at_start_of_monster_turn - g.u.uhp + dmg,
                       g.gu.uhp_at_start_of_monster_turn, g.u.uhpmax);

        /* note: this could reduce dmg to 0 if u.uhpmax==1 */
        dmg = g.u.uhp - 1;
        g.u.usaving_grace = 1; /* used up */
        g.gs.saving_grace_turn = true;
        end_running(true);
        if (g.u.usleep)
            unmul("Suddenly you wake up!");
        if (is_fainted())
            reset_faint();
    }
    return dmg;
}





