/* C ref: cmd.c:1574-1586 do_reqmenu(void) — the 'm' prefix.
 *     if (iflags.menu_requested) {
 *         Norep("Double %s prefix, canceled.", visctrl(cmd_from_func(do_reqmenu)));
 *         iflags.menu_requested = FALSE;
 *         return ECMD_CANCEL;
 *     }
 *     iflags.menu_requested = TRUE;
 *     return ECMD_OK;
 * Every reader of iflags.menu_requested in this port was already ported (doeat,
 * dodrink, dopickup, doorganize, ...); only the one WRITER was a throwing stub,
 * which is why iactions.c's IA_EAT_OBJ / IA_QUAFF_OBJ / IA_TIP_CONTAINER rows
 * could not queue their m-prefix. */
export async function do_reqmenu() {
    const g = game;
    if (!g.iflags) g.iflags = {};
    if (g.iflags.menu_requested) {
        await _Norep('Double %s prefix, canceled.', _binds_visctrl(cmd_from_func('do_reqmenu')));
        g.iflags.menu_requested = false;
        return STETH_ECMD_CANCEL;
    }
    g.iflags.menu_requested = true;
    return STETH_ECMD_OK;
}

