async function pooleffects_lava_destroy_inventory(usurvive = false, bootsBurned = 0) {
    const g = game;
    g._lavaSummaryEmitted = false;
    /* trap.c:6866-6869 — the burnt boots bump both burncount and burnmesgcount */
    let count = bootsBurned;
    let burnmesgcount = bootsBurned;
    for (let obj = g.invent, next; obj; obj = next) {
        next = obj.nobj;
        if ((obj.o_id | 0) === (g._lavaProtectOid | 0)) { obj.in_use = 1; continue; }
        /* C trap.c:6897-6900: the Book survives lava, but visibly glows
         * when the hero can survive too, even if it was not marked in_use. */
        if ((obj.otyp | 0) === _IA_SPE_BOOK_OF_THE_DEAD_OTYP) {
            if (usurvive && !_vision_Blind())
                await pline('%s glows a strange %s, but remains intact.',
                            The(_fw_xname(obj)), hcolor('dark red'));
            continue;
        }
        if (!obj.in_use) continue;
        if (obj.owornmask) {
            /* trap.c emits a burn line for each worn object on the life-saved /
             * wizard-survival arm before remove_worn_item(). */
            if (usurvive)
                await pline(`${Yobjnam2(obj, 'burst')} into flame!`);
            if (usurvive)
                burnmesgcount++;
            await _remove_worn_item_thrown(obj, true);
            /* trap.c:6905-6909: removal can page its plines, but does not
             * flush again after toggle_blindness sets the status dirty. */
            if (_topline_more_pending())
                await flush_screen(1, false);
        }
        await useupall(obj);
        count++;
    }
    g._lavaBurnCount = count;
    if (usurvive && count > burnmesgcount) {
        g._lavaSummaryEmitted = true;
        /* C topl.c update_topl:262-266 — a message that does not fit beside the
           pending topline raises its more() BEFORE it is drawn; an ESC there
           sets WIN_STOP, which the urgent_pline("You burn to a crisp...") that
           follows in lava_effects wipes.  The 63-char summary never fits
           beside the burst line, so page that line now. */
        const other = count - burnmesgcount;
        const prefix = burnmesgcount > 0
            ? (other === 1 ? 'Another' : 'Other')
            : (count === 1 ? 'An' : 'Some');
        const summary = `${prefix} item${other === 1 ? '' : 's'} in your inventory `
            + `${other === 1 ? 'has' : 'have'} been destroyed.`;
        const _pend = String(g._pending_message || '');
        /* pline.c:266-272 recalculates vision (a destroyed lit lamp's
           del_light_source set vision_full_recalc) before putmesg() raises
           the more(), so the frozen --More-- frame already shows the hero. */
        if (_pend && g.vision_full_recalc)
            vision_recalc(0);
        if (_pend && summary.length + _pend.length + 3 >= 80 - 8)
            await force_more(_pend);
        await pline(summary);
    }
}

export async function pooleffects_lava_effects() {
    const g = game;
    const u = g.u;
    if (!g.iflags) g.iflags = {};
    /* C trap.c:6800 `const int dmg = d(6, 6);` — see above: unconditional. */
    const dmg = d(6, 6);
    if (g.iflags.in_lava_effects)
        return false;                       /* "Skipping recursive lava_effects()." */
    feel_newsym(u.ux, u.uy);                /* in case Blind, map the lava here */
    await pooleffects_burn_away_slime();
    if (pooleffects_likes_lava(u.umonnum | 0))
        return false;

    let bootsBurned = 0;
    const fireres = pooleffects_Fire_resistance();
    let wwalking = pooleffects_Wwalking();
    let usurvive = fireres || (wwalking && dmg < (u.uhp | 0));
    if (!usurvive) {
        pooleffects_lava_flag_inventory();
    }
    /* C trap.c:6858-6869 — boots burn first, so that water walking is gone
       before the sink test below. */
    if (u.uarmf && (u.uarmf.in_use
                    || ((MKOBJ_OC_MATERIAL[u.uarmf.otyp | 0] | 0) <= 8
                        && !u.uarmf.oerodeproof))) {
        const boots = u.uarmf;
        await pline(`${Yobjnam2(boots, 'burst')} into flame!`);
        bootsBurned++;
        g.iflags.in_lava_effects = (g.iflags.in_lava_effects | 0) + 1;
        await Boots_off();
        if (_topline_more_pending())
            await flush_screen(1);
        if ((boots.o_id | 0) !== (g._lavaProtectOid | 0))
            await useup(boots);
        g.iflags.in_lava_effects--;
        /* C reevaluates Wwalking after Boots_off(); the property may have
         * disappeared with the burned boots before the lava fall test. */
        wwalking = pooleffects_Wwalking();
    }

    if (!fireres) {
        if (wwalking) {
            await pline(`The ${hliquid('lava')} here burns you!`); /* trap.c:6873 */
            if (usurvive) {
                await losehp(dmg, 'molten lava', KILLED_BY);
                /* goto burn_stuff (trap.c:6874-6877, 6992-6994) */
                await destroy_items_zap(true, AD_FIRE_LAVA, dmg);
                await ignite_items_mu(g.invent);
                return false;
            }
        } else {
            await pline(`You fall into the ${waterbody_name(u.ux, u.uy)}!`);
        }

        usurvive = pooleffects_Lifesaved() || discover();
        if (wizard())
            usurvive = true;
        /* C continues into the burn loop after this inventory pass even when
           `usurvive` is true; that flag controls only the per-item messages. */
        g.iflags.in_lava_effects = (g.iflags.in_lava_effects | 0) + 1;
        await pooleffects_lava_destroy_inventory(usurvive, bootsBurned);

        /* C trap.c:6921-6923 — boil_away is a polymorph-form test. */
        const boil_away = (u.umonnum === PM_WATER_ELEMENTAL
                           || u.umonnum === PM_STEAM_VORTEX
                           || u.umonnum === PM_FOG_CLOUD);
        /* C trap.c:6926-6961 — the burn loop and survivor relocation. */
        /* C display.c:2285-2288 — `u.uhp = -1` flags nothing, so the status
           window keeps the pre-death line until done() sets disp.botlx and calls
           bot().  This port recomputes the status from live `u` at every render,
           so freeze the frame here and let the more() below page over it. */
        let burntry;
        for (burntry = 0; burntry < 2; ++burntry) {
            u.uhp = -1; /* trap.c:6928: bot() now preserves the last paint. */
            g.svk ||= {};
            g.svk ||= {};
            g.svk.killer ||= { id: 0, format: 0, name: "", next: null };
            g.svk.killer.format = KILLED_BY;
            g.svk.killer.name = 'molten lava';
            await urgent_pline(boil_away ? 'You boil away...' : 'You burn to a crisp...');
            /* C pline.c:273-276 flushes the map before putmesg(), including
             * vision restored by burnt eyewear (potion.c:348).  Freeze AFTER
             * that flush; botl.c:259 still preserves the old status at -1 HP. */
            const frozenPaint = capture_painted_frame_with_status();
            if (frozenPaint) g._paintedSnapshot = frozenPaint;
            /* C end.c:1082 — done() joins "But wait..." onto the live
               "You burn to a crisp..." topline when life saving applies, so
               only page it ourselves when it does not. */
            if (![u.uprops?.[LIFESAVED], u.uprops?.['LIFESAVED']].some(p => p?.extrinsic | 0))
                await force_more(g._pending_message);
            g._paintedSnapshot = null;
            await done(BURNING);
            if (g.program_state?.gameover) return true;
            if (await safe_teleds(TELEDS_ALLOW_DRAG | TELEDS_TELEPORT)) break;
            await pline("You're still burning.");
        }
        g.iflags.in_lava_effects--;
        if (burntry === 2) {
            /* C trap.c:6944-6955 jumps to burn_stuff after granting temporary
             * protection when both escape attempts fail. */
            if (!pooleffects_Fire_resistance()) _set_prop_itimeout(FIRE_RES, 5);
            if (!pooleffects_Wwalking()) _set_prop_itimeout(WWALKING, 5);
            await destroy_items_zap(true, AD_FIRE_LAVA, dmg);
            await ignite_items_mu(g.invent);
            return false;
        }
        await rescued_from_terrain(BURNING);
        await spoteffects(false);
        return true;
    }
    if (!pooleffects_Wwalking() && (!u.utrap || (u.utraptype | 0) !== TT_LAVA)) {
        /* C trap.c:6965-6985 — fire-resistant hero not yet stuck sinks in. */
        const boil_away = !pooleffects_Fire_resistance();
        set_utrap((rn1(4, 4) + ((boil_away ? 2 : rn1(4, 12)) << 8)) >>> 0, TT_LAVA);
        await pline(`You sink into the ${waterbody_name(u.ux, u.uy)}`
                    + `${!boil_away ? ', but it only burns slightly' : ' and are about to be immolated'}!`);
        if (!boil_away) monstseesu_gz(0x0002 /* M_SEEN_FIRE */);
        else monstunseesu_gz(0x0002);
        if ((u.uhp | 0) > 1)
            await losehp(!boil_away ? 1 : Math.trunc((u.uhp | 0) / 2), 'molten lava', KILLED_BY);
    }
    /* C: fire-resistant heroes skip the sink/fall branch and reach
     * destroy_items(AD_FIRE, dmg), then return to the movement loop.  The
     * inventory damage selector has no live witness here; preserve the
     * nonfatal control flow rather than halting after the lava contact. */
    await destroy_items_zap(true, AD_FIRE_LAVA, dmg); /* burn_stuff, trap.c:6993 */
    await ignite_items_mu(g.invent);
    return false;
}
