function binding_statics() {
    return (game._command_binding_statics ||= {
        back_dir_cmd: Array.from({ length: N_DIRS }, () => Array(N_MOVEMODES).fill(null)),
        back_dir_key: Array.from({ length: N_DIRS }, () => Array(N_MOVEMODES).fill(0)),
        backed_dir_cmd: false,
        unrestonspace: null,
    });
}

// C cmd.c:2109 cmdbind_get(uchar key).
export function cmdbind_get(key) {
    key &= 0xff;
    let bind = command_state().cmdbinds;
    if (!key)
        return null;
    while (bind) {
        if (bind.key === key)
            return bind;
        bind = bind.next;
    }
    return bind;
}

export function cmdbind_add(key, extcmd, user) {
    key &= 0xff;
    let bind = cmdbind_get(key);
    if (!key)
        return;
    if (!extcmd && bind) {
        cmdbind_remove(key);
        return;
    }
    if (bind) {
        bind.cmd = extcmd;
        bind.userbind = !!user;
        if (bind.param)
            bind.param = null;
        return;
    } else {
        // C allocates a NULL-command node too, if the key was absent.
        bind = { key, userbind: !!user, param: null, cmd: extcmd,
            next: command_state().cmdbinds };
        command_state().cmdbinds = bind;
    }
}

export function cmdbind_remove(key) {
    key &= 0xff;
    let bind = command_state().cmdbinds;
    let prev = null;
    while (bind) {
        if (bind.key === key) {
            if (prev)
                prev.next = bind.next;
            else
                command_state().cmdbinds = bind.next;
            // JS GC reclaims the unlinked C node and its parameter.
            return;
        }
        prev = bind;
        bind = bind.next;
    }
}

export function cmdbind_freeall() {
    const cmd = command_state();
    while (cmd.cmdbinds) {
        const next = cmd.cmdbinds.next;
        cmd.cmdbinds = next;
    }
}

export function cmdbind_swapkeys(key1, key2) {
    key1 &= 0xff;
    key2 &= 0xff;
    const bind1 = cmdbind_get(key1);
    const bind2 = cmdbind_get(key2);
    if (bind1 && bind2) {
        bind1.key = key2;
        bind2.key = key1;
    }
}

export function bind_mousebtn(btn, command) {
    const cmd = command_state();
    if (btn < 1 || btn > 2) {
        config_error_add('Wrong mouse button, valid are 1-%i', 2);
        return false;
    }
    --btn;
    if (lowcase(command) === 'nothing') {
        cmd.mousebtn[btn] = null;
        return true;
    }
    for (const extcmd of EXTCMDLIST) {
        if (lowcase(command) !== lowcase(extcmd.name))
            continue;
        if (!(extcmd.flags & MOUSECMD))
            continue;
        cmd.mousebtn[btn] = extcmd;
        return true;
    }
    return false;
}

export function bind_key(key, command, user) {
    key &= 0xff;
    if (lowcase(command) === 'nothing') {
        cmdbind_remove(key);
        return true;
    }
    let buf = command, p = null;
    const left = buf.indexOf('('), last = buf.lastIndexOf(')');
    if (left !== -1 && last !== -1 && last > left) {
        p = buf.substring(left + 1, last);
        buf = buf.substring(0, left);
    }
    for (const extcmd of EXTCMDLIST) {
        if (lowcase(buf) !== lowcase(extcmd.name))
            continue;
        if (extcmd.flags & INTERNALCMD)
            continue;
        cmdbind_add(key, extcmd, user);
        if (extcmd.flags & CMD_PARAM) {
            if (p === null) {
                config_error_add("'%s' requires a parameter", buf);
            } else {
                const bind = cmdbind_get(key);
                const maxlen = Math.min(30, p.length) + 1;
                if (maxlen <= 1)
                    config_error_add('Required parameter cannot be empty');
                else
                    bind.param = p.substring(0, maxlen - 1);
            }
        } else if (p !== null && p.length > 0) {
            config_error_add("'%s' does not take a parameter", buf);
        }
        return true;
    }
    return false;
}

export function bind_key_fn(key, fn) {
    for (const extcmd of EXTCMDLIST) {
        if (extcmd.func !== fn)
            continue;
        if (extcmd.flags & INTERNALCMD)
            continue;
        cmdbind_add(key, extcmd, false);
        return true;
    }
    return false;
}

export function commands_init() {
    for (const extcmd of EXTCMDLIST)
        if (extcmd.key)
            cmdbind_add(extcmd.key, extcmd, false);
    bind_mousebtn(1, 'therecmdmenu');
    bind_mousebtn(2, 'clicklook');
    bind_key(C('l'), 'redraw', false);
    bind_key(104, 'help', false);
    bind_key(106, 'jump', false);
    bind_key(107, 'kick', false);
    bind_key(108, 'loot', false);
    bind_key(C('n'), 'annotate', false);
    bind_key(78, 'name', false);
    bind_key(117, 'untrap', false);
    bind_key(53, 'run', false);
    bind_key(M('5'), 'rush', false);
    bind_key(45, 'fight', false);
    bind_key(M('O'), 'overview', false);
    bind_key(M('2'), 'twoweapon', false);
    bind_key(M('N'), 'name', false);
}

export function ext_func_tab_from_func(fn) {
    for (const extcmd of EXTCMDLIST)
        if (extcmd.func === fn)
            return extcmd;
    return null;
}

export function cmd_from_func(fn) {
    if (typeof fn === 'function') fn = fn.name;
    let ret = 0;
    const cmd = command_state();
    for (let bind = cmd.cmdbinds; bind; bind = bind.next) {
        const i = bind.key;
        if (i === 32)
            continue;
        if (((i >= 48 && i <= 57) || (i === 45 && fn === 'do_fight'))
            && !cmd.num_pad)
            continue;
        if (bind.cmd && bind.cmd.func === fn) {
            if (i >= 32 && i <= 126)
                return i;
            else
                ret = (i << 24) >> 24; // C cmd.c:3058: ret = (char) i.
        }
    }
    const bind = cmdbind_get(32);
    if (bind && bind.cmd && bind.cmd.func === fn)
        return 32;
    return ret;
}

export function bind_specialkey(key, command) {
    for (const b of spkeys_binds) {
        if (!b.name || command !== b.name)
            continue;
        command_state().spkeys[b.nhkf] = key & 0xff;
        return true;
    }
    return false;
}

// C cmd.c:3344. Backups are genuine command references, not rebuilt defaults.
const EXTCMD_FLAGS_PRISTINE = EXTCMDLIST.map(e => e.flags);

export function reset_commands(initial) {
    /* C's extcmdlist flags live for one process; the port replays several
     * games per process, so undo a prior game's AUTOCOMPLETE= edits. */
    if (initial)
        EXTCMDLIST.forEach((e, i) => { e.flags = EXTCMD_FLAGS_PRISTINE[i]; });
    const cmd = command_state(), saved = binding_statics();
    const { back_dir_cmd, back_dir_key } = saved;
    const sdir = 'hykulnjb><', sdir_swap_yz = 'hzkulnjb><';
    const ndir = '47896321><', ndir_phone_layout = '41236987><';
    const ylist = [121, 89, C('y'), M('y'), M('Y'), M(C('y'))];
    let flagtemp, c, updated = 0;
    if (initial) {
        updated = 1;
        cmd.num_pad = false;
        cmd.pcHack_compat = cmd.phone_layout = cmd.swap_yz = false;
        for (const b of spkeys_binds)
            cmd.spkeys[b.nhkf] = b.key;
        commands_init();
    } else {
        if (saved.backed_dir_cmd) {
            for (let dir = 0; dir < N_DIRS; dir++)
                for (let mode = 0; mode < N_MOVEMODES; mode++)
                    cmdbind_add(back_dir_key[dir][mode], back_dir_cmd[dir][mode], false);
        }
        flagtemp = !!game.iflags?.num_pad;
        if (flagtemp !== cmd.num_pad) {
            cmd.num_pad = flagtemp;
            ++updated;
        }
        flagtemp = (game.iflags?.num_pad_mode & 1) ? !cmd.num_pad : false;
        if (flagtemp !== cmd.swap_yz) {
            cmd.swap_yz = flagtemp;
            ++updated;
            for (const y of ylist) {
                c = y & 0xff;
                cmdbind_swapkeys(c, c + 1);
            }
        }
        flagtemp = (game.iflags?.num_pad_mode & 1) ? cmd.num_pad : false;
        if (flagtemp !== cmd.pcHack_compat) {
            cmd.pcHack_compat = flagtemp;
            ++updated;
            c = M('0') & 0xff;
            if (cmd.pcHack_compat)
                cmdbind_add(c, ext_func_tab_from_func('dotypeinv'), false);
            else
                cmdbind_remove(c);
        }
        flagtemp = (game.iflags?.num_pad_mode & 2) ? cmd.num_pad : false;
        if (flagtemp !== cmd.phone_layout) {
            cmd.phone_layout = flagtemp;
            ++updated;
            for (let i = 0; i < 3; i++) {
                c = 49 + i;
                cmdbind_swapkeys(c, c + 6);
                c = (M('1') & 0xff) + i;
                cmdbind_swapkeys(c, c + 6);
            }
        }
    }
    if (updated)
        cmd.serialno = (cmd.serialno + 1) >>> 0;
    cmd.dirchars = !cmd.num_pad ? (!cmd.swap_yz ? sdir : sdir_swap_yz)
        : (!cmd.phone_layout ? ndir : ndir_phone_layout);
    cmd.alphadirchars = !cmd.num_pad ? cmd.dirchars : sdir;
    for (let dir = 0; dir < N_DIRS; dir++) {
        for (let mode = MV_WALK; mode < N_MOVEMODES; mode++) {
            let di = cmd.dirchars.charCodeAt(dir);
            if (!cmd.num_pad) {
                if (mode === MV_RUN) di = highc(di);
                else if (mode === MV_RUSH) di = C(di);
            } else {
                if (mode === MV_RUN) di = M(di);
                else if (mode === MV_RUSH) di = M(di);
            }
            back_dir_key[dir][mode] = di;
            const bind = cmdbind_get(di);
            back_dir_cmd[dir][mode] = bind ? bind.cmd : null;
            cmdbind_remove(di);
        }
    }
    saved.backed_dir_cmd = true;
    for (let i = 0; i < N_DIRS; i++) {
        bind_key_fn(cmd.dirchars.charCodeAt(i), MOVE_FUNCS[i][MV_WALK]);
        if (!cmd.num_pad) {
            bind_key_fn(highc(cmd.dirchars.charCodeAt(i)), MOVE_FUNCS[i][MV_RUN]);
            bind_key_fn(C(cmd.dirchars.charCodeAt(i)), MOVE_FUNCS[i][MV_RUSH]);
        } else {
            bind_key_fn(M(cmd.dirchars.charCodeAt(i)), MOVE_FUNCS[i][MV_RUN]);
        }
    }
    update_rest_on_space();
    cmd.extcmd_char = cmd_from_func('doextcmd');
}

const restonspace = { key: 32, name: 'wait',
    desc: "rest one move via 'rest_on_space' option", func: 'donull', flags: 0x0081 };

export function update_rest_on_space() {
    const saved = binding_statics(), bind = cmdbind_get(32);
    if (bind && bind.cmd !== restonspace)
        saved.unrestonspace = bind.cmd;
    cmdbind_add(32, game.flags?.rest_on_space ? restonspace : saved.unrestonspace, false);
}

export function cmd_from_ecname(ecname) {
    ensureBinds();
    for (const extcmd of EXTCMDLIST) {
        if (extcmd.name !== ecname) continue;
        const key = cmd_from_func(extcmd.func);
        return key ? visctrl(key) : `#${ecname}`;
    }
    return '';
}

/* C cmd.c:getdir — interactive direction input, help/redraw retry, repeat
 * recording, orientation and impairment. Returns 1 for a valid direction,
 * 0 for cancellation or an invalid direction. Queue/read-buffer consumption,
 * full yn_function/input-state ownership, mouse/getpos, fuzzer and alternate
 * binding initialization remain open; the typed queue primitives alone do
 * not implement those consumer paths. */
/* C ref: src/decl.c:96 — `const char quitchars[] = " \r\n\033";`.  SPACE, CR,
 * LF and ESC, and nothing else.  This constant read '\x1b\x07\x03' (ESC, BEL,
 * ^C), which is not any C character class: it omitted the three characters
 * that actually cancel a direction prompt and added two that do not.  A SPACE
 * at "In what direction?" therefore fell through to the cmd.c:4098
 * `!strchr(quitchars, dirsym)` branch that C skips, drew the cmdassist
 * help_dir window, and ate an extra keystroke. */
const QUITCHARS = ' \r\n\x1b';

/* `opts.noPrompt` suppresses ONLY the prompt paint (the message, the flush and
 * the parked cursor), never the read or any of C's key handling below it.
 *
 * It exists for one caller: dofire()'s cmdq-drain tail (js/cmd.js
 * _fire_throw_obj), where the topline is deliberately left holding the
 * fireassist swap's committed --More-- frame across the getdir call instead of
 * being repainted.  C gets that for free — tty_yn_function writes over a
 * topline that the tty is still showing, and the recorded frame at that
 * nhgetch is the swap's — while this port paints each frame explicitly, so the
 * retention has to be asked for.  DISPLAY-channel only; no caller may use it
 * to skip a prompt C would have written. */
export async function getdir(_s, opts = {}) {
    const g = game;
    const u = g.u = g.u || {};
    let noPrompt = !!opts.noPrompt;
    let cmdq = cmdq_pop();
    // C's retry label. A retained fireassist frame applies to the first read
    // only; explicit help/redraw returns here and paints a fresh prompt.
    for (;;) {
        const result = await _getdir_read(g, u, _s, noPrompt, cmdq);
        // A help retry does not pop a second queued command.
        cmdq = null;
        noPrompt = false;
        if (result !== null)
            return result;
    }
}

/* null is the internal equivalent of C's `goto retry`; 0 and 1 are getdir's
 * caller-visible results. No nested getdir call or extra command dispatch. */
async function _getdir_read(g, u, s, noPrompt, cmdq) {
    let keyCode;
    if (cmdq) {
        if (cmdq.typ === CMDQ_DIR) {
            // v5 movementdirs puts DOWN at 8 and UP at 9. The frozen JS
            // constants have those names reversed; use the C enum here.
            const dir = !cmdq.dirz ? xytodir(cmdq.dirx, cmdq.diry)
                : cmdq.dirz > 0 ? 8 : 9;
            keyCode = (g.Cmd?.dirchars || 'hykulnjb><').charCodeAt(dir);
        } else if (cmdq.typ === CMDQ_KEY) {
            keyCode = cmdq.key;
        } else {
            cmdq_clear(CQ_CANNED);
            keyCode = 0;
            await impossible('getdir: command queue had no dir?');
        }
        // C frees the detached node and jumps to got_dirsym, bypassing
        // prompt/input-state changes, redraw handling and repeat recording.
    } else {
        g.program_state.input_state = 3; // getdirInp
        if (g.gi?.in_doagain || g.readchar_queue?.charCodeAt(0)) {
            keyCode = await readchar();
        } else {
            // The shared reader owns acknowledgment, answered-prompt history,
            // last_msg and the transition from getdirInp back to otherInp.
            const dirPrompt = (s != null && s.charAt(0) !== '^')
                ? s : 'In what direction?';
            const reply = await yn_function(dirPrompt, null, '\0', false,
                { retainFrame: noPrompt });
            keyCode = typeof reply === 'number' ? reply : reply.charCodeAt(0);
            /* C cmd.c:3995-4013 — for the fuzzer, usually force the result to
             * be a valid direction, but sometimes let it exercise the invalid
             * direction code; no-diagonal grid-bug forms are deliberately not
             * enforced here either. */
            if (g.iflags?.debug_fuzzer && rn2(20)) {
                const dirchars = g.Cmd?.dirchars || 'hykulnjb><';
                switch (rn2(20)) {
                case 0: {
                    const selfDir = rn2(2);
                    keyCode = g.Cmd?.spkeys?.[selfDir ? NHKF_GETDIR_SELF : NHKF_ESC]
                        ?? (selfDir ? 46 : 27); /* reset_commands defaults */
                    break;
                }
                case 1:
                    /* movementdirs: DIR_DOWN=8, DIR_UP=9 (C enum order) */
                    keyCode = dirchars.charCodeAt(rn2(2) ? 8 : 9);
                    break;
                default:
                    keyCode = dirchars.charCodeAt(rn2(N_DIRS));
                    break;
                }
            }
        }
        /* C clear_nhwindow(WIN_MESSAGE), including buffered reads. */
        g._pending_message = '';
        // C retries redraw before recording the reply in CQ_REPEAT.
        if (redraw_cmd(keyCode)) {
            await docrt_flags(0x04); // docrtRefresh
            return null;
        }
        if (!g.gi?.in_doagain)
            cmdq_add_key(CQ_REPEAT, keyCode);
    }
    /* movecmd() keys off the raw keycode (C's `uchar sym`), so keep both. */
    const dircode = typeof keyCode === 'number'
        ? (keyCode & 0xff)
        : (String(keyCode ?? '').charCodeAt(0) | 0);
    const dirsym = typeof keyCode === 'number' ? String.fromCharCode(keyCode) : '';
    /* C cmd.c:4696 — self-direction keys '.' or 's' → u.dx=u.dy=u.dz=0 */
    if (dircode === (g.Cmd?.spkeys?.[NHKF_GETDIR_SELF] ?? 46)
        || dircode === (g.Cmd?.spkeys?.[NHKF_GETDIR_SELF2] ?? 115)) {
        u.dx = 0; u.dy = 0; u.dz = 0;
        confdir(false);
        return 1;
    }
    if (dircode === (g.Cmd?.spkeys?.[NHKF_GETDIR_MOUSE] ?? 95 /* '_' */)) {
        const qbuf = `desired location, then type '${
            visctrl(g.Cmd?.spkeys?.[NHKF_GETPOS_PICK_Q] ?? 44 /* ',' */)}' for left click, '${
            visctrl(g.Cmd?.spkeys?.[NHKF_GETPOS_PICK] ?? 46 /* '.' */)}' for right`;
        /* cc.x = u.ux, cc.y = u.uy — starting cursor location for getpos(). */
        const cc = { x: u.ux | 0, y: u.uy | 0 };
        let pos = await getpos(cc, true, qbuf);
        let mod;
        if (pos < 0) {
            /* ESC or other rejection */
            u.dx = u.dy = u.dz = 0;
            mod = 0; /* neither CLICK_1 nor CLICK_2 */
        } else {
            /* caller expects simulated click to be relative to hero's spot */
            u.dx = (cc.x | 0) - (u.ux | 0);
            u.dy = (cc.y | 0) - (u.uy | 0);
            /* non-zero getdir_click actually means ok to click farther than
             * one spot away from hero; adjacent click is always allowed */
            if (!g.iflags?.getdir_click) {
                u.dx = u.dx < 0 ? -1 : (u.dx > 0 ? 1 : 0);
                u.dy = u.dy < 0 ? -1 : (u.dy > 0 ? 1 : 0);
            }
            u.dz = 0;
            switch (pos + NHKF_GETPOS_PICK) {
            case NHKF_GETPOS_PICK_Q: /* 1: quick:   ',' */
            case NHKF_GETPOS_PICK_O: /* 2: once:    ';' */
                mod = CLICK_1;
                break;
            case NHKF_GETPOS_PICK:   /* 0: normal:  '.' */
            case NHKF_GETPOS_PICK_V: /* 3: verbose: ':' */
                mod = CLICK_2;
                break;
            default:
                /* C: "something which should never happen" */
                await impossible(`getpos successful but not one of [.,;:] (${pos})`);
                mod = 0; /* neither CLICK_1 nor CLICK_2 */
                pos = -1; /* return failure */
                break;
            }
        }
        if (g.iflags?.getdir_click)
            g.iflags.getdir_click = mod;
        return pos >= 0;
    }
    /* C cmd.c:4095 — `else if (!(is_mov = movecmd(dirsym, MV_ANY)) && !u.dz)`.
     * movecmd writes u.dx/u.dy/u.dz for every bound direction key (walk, run
     * and rush spellings alike, plus '<'/'>' which set u.dz and make movecmd
     * return 0), so this one call replaces the lowercase table, the '<'/'>'
     * arms and the quitchars pre-test that used to sit in front of them. */
    const is_mov = movecmd(dircode, MV_ANY);
    if (is_mov || u.dz) {
        if (is_mov && !dxdy_moveok()) {
            await pline("You can't orient yourself that direction.");
            return 0;
        }
        /* C cmd.c:4116-4117 — the tail every successful getdir falls through
         * to: `if (!u.dz) confdir(FALSE); return 1;`.  confdir is not
         * RNG-neutral (u_maybe_impaired draws when the hero is confused). */
        if (!u.dz)
            confdir(false);
        return 1;
    }
    /* C cmd.c:4098 — `if (!strchr(quitchars, dirsym))`, INSIDE the
     * invalid-direction arm: a quitchar cancels silently. */
    // strchr(quitchars, NUL) finds the string terminator in C.
    if (dircode === 0 || QUITCHARS.indexOf(dirsym) >= 0) {
        return 0;
    }
    const help_requested = dircode === (g.Cmd?.spkeys?.[NHKF_GETDIR_HELP] ?? 63);
    let did_help = false;
    if (help_requested || cmdassist_on()) {
        did_help = await help_dir(s && s.charAt(0) === '^' ? dirsym : '\0',
            ESC_KEY, help_requested ? null : 'Invalid direction key!');
        if (help_requested)
            return null;
    }
    if (!did_help)
        await pline('What a strange direction!');
    return 0;
}

/* C ref: cmd.c:4846 help_dir(sym, spkey, msg) — the cmdassist invalid-direction
 * window.  Builds an NHW_TEXT window and display_nhwindow(win, FALSE)s it, which
 * on tty clears the screen, paints the lines from row 0 and pins a "--More--" to
 * row 23 that consumes one page-ack keystroke.  Always returns TRUE once the
 * window is shown (the !viawindow early-return is #if 0'd out in 3.7).
 *
 * The caller's special key selects ordinary getdir or prefix help. Direction
 * and self keys come from the shared live bindings; NODIAG(u.umonnum) selects
 * the grid-bug diagram rather than assuming the ordinary hero shape.
 * DISPLAY-CHANNEL ONLY: no RNG. */
export async function help_dir(sym, spkey, msg) {
    const byte = c => typeof c === 'number' ? c & 0xff : c.charCodeAt(0) & 0xff;
    const prefixhandling = byte(spkey) !== (game.Cmd?.spkeys?.[0] ?? 27);
    const lines = [];
    /* C cmd.c:4911-4915 — buf is empty (the bad-prefix arms are #if 0'd), so the
     * general invalid-direction message is shown. */
    if (msg) {
        lines.push(`cmdassist: ${msg}`);
        lines.push('');
    }
    let symcode = byte(sym);
    if (!prefixhandling && ((symcode >= 64 && symcode <= 90)
        || (symcode >= 97 && symcode <= 122) || symcode === 91)) {
        if (symcode >= 97 && symcode <= 122) symcode -= 32;
        const ctrl = symcode - 65 + 1, letter = String.fromCharCode(symcode);
        const explain = dowhatdoes_core(ctrl), wiz_only = 'EFGIVW'.includes(letter);
        if (explain !== null && (!wiz_only || game.flags?.debug)) {
            lines.push(`Are you trying to use ^${letter}${wiz_only ? '' : ' as specified in the Guidebook'}?`);
            lines.push('');
            lines.push(explain);
            lines.push('');
            lines.push('To use that command, hold down the <Ctrl> key as a shift');
            lines.push(`and press the <${letter}> key.`);
            lines.push('');
        }
    }
    const nodiag = (game.u?.umonnum | 0) === 116; // NODIAG: PM_GRID_BUG
    lines.push(`Valid direction keys${prefixhandling ? ' to do that' : ''}`
               + `${nodiag ? ' in your current form' : ''} are:`);
    lines.push(...show_direction_keys(!prefixhandling ? '.' : ' ', nodiag));
    if (!prefixhandling) {
        lines.push('');
        lines.push('          <  up');
        lines.push('          >  down');
        /* C: Sprintf(buf, "       %4s  direct at yourself",
         *            visctrl(spkeys[NHKF_GETDIR_SELF]))  — "." right-justified
         * in 4 columns after 7 spaces. */
        const selfi = game.Cmd?.num_pad ? NHKF_GETDIR_SELF2 : NHKF_GETDIR_SELF;
        lines.push('       ' + visctrl(game.Cmd?.spkeys?.[selfi] ?? (selfi === NHKF_GETDIR_SELF ? 46 : 115)).padStart(4)
            + '  direct at yourself');
    }
    if (msg) {
        /* C cmd.c:4957-4960 — non-null msg means this wasn't an explicit user
         * request, so append the suppression hint. */
        lines.push('');
        lines.push('(Suppress this message with !cmdassist in config file.)');
    }
    await display_text_window(lines);
    return true;
}

const MISC_KEYS = [
    { nhkf: NHKF_ESC, desc: 'cancel current prompt or pending prefix', numpad: false },
    { nhkf: NHKF_COUNT,
      desc: 'Prefix: for digits when preceding a command with a count', numpad: true },
];

/* C ref: cmd.c:3862-3874 spkey_name(nhkf) — the spkeys_binds[] name, except
 * NHKF_ESC which reports "escape" rather than its NULL binding name. */
function spkey_name(nhkf) {
    if (nhkf === NHKF_ESC) return 'escape';
    if (nhkf === NHKF_COUNT) return 'count';
    return null;
}

const WIZMODECMD = 0x0004;

/* C ref: cmd.c:3453-3468 keylist_func_has_key(extcmd, skip_keys_used) — is some
 * key (outside skip_keys_used[]) bound to this exact extcmdlist entry?
 * ext_cmd_from_key() returns the EXTCMDLIST element itself, so the C pointer
 * comparison `bind->cmd == extcmd` is a JS identity comparison. */
function keylist_func_has_key(extcmd, skip_keys_used) {
    for (let i = 0; i < 256; ++i) {
        if (skip_keys_used[i])
            continue;
        const cmd = ext_cmd_from_key(i);
        if (cmd && cmd === extcmd)
            return true;
    }
    return false;
}

/* C ref: cmd.c:3470-3530 keylist_putcmds(datawin, docount, incl, excl, keys_used).
 * `docount` returns the row count without emitting or marking keys used. */
function keylist_putcmds(datawin, docount, incl_flags, excl_flags, keys_used) {
    const g = game;
    const keys_already_used = new Array(256).fill(false);
    let count = 0;
    const rest_on_space = !!(g.flags && g.flags.rest_on_space);

    for (let i = 0; i < 256; i++) {
        const key = i & 0xff;
        keys_already_used[i] = keys_used[i];
        if (keys_used[i])
            continue;
        if (key === 0x20 /* ' ' */ && !rest_on_space)
            continue;
        const cmd = ext_cmd_from_key(key);
        if (cmd) {
            if ((incl_flags && !(cmd.flags & incl_flags))
                || (excl_flags && (cmd.flags & excl_flags)))
                continue;
            if (docount) {
                count++;
                continue;
            }
            /* Only "#toggle" carries CMD_PARAM and it has no default key; a
             * BINDINGS rc line (e.g. BINDINGS=^B:toggle(autoquiver)) binds it,
             * and the parameter lives on the BIND, not the EXTCMDLIST entry.
             * C ref: cmd.c:2830-2833 — bind->param. */
            if ((cmd.flags & CMD_PARAM) !== 0)
                datawin.push(`${_pad_l(key2txt(key), 7)} ${_pad_l(cmd.name, 13)} ${cmd.desc} "${cmdbind_get(key).param}"`);
            else
                datawin.push(`${_pad_l(key2txt(key), 7)} ${_pad_l(cmd.name, 13)} ${cmd.desc}`);
            keys_used[i] = true;
        }
    }
    /* also list commands that lack key assignments; most are wizard mode */
    for (const extcmd of EXTCMDLIST) {
        if ((incl_flags && !(extcmd.flags & incl_flags))
            || (excl_flags && (extcmd.flags & excl_flags)))
            continue;
        if (keylist_func_has_key(extcmd, keys_already_used))
            continue;
        if (docount) {
            count++;
            continue;
        }
        /* '#'+20 for one column here == 7+' '+13 for two columns above */
        datawin.push(`#${_pad_l(extcmd.name, 20)} ${extcmd.desc}`);
    }
    return count;
}

/* C ref: cmd.c:3532-3679 dokeylist() — help menu item 'j', "list all keys and
 * their bindings, like dat/hh but dynamic".  GENERALCMD: no turn, no RNG. */
export async function dokeylist() {
    const g = game;
    const keys_used = new Array(256).fill(false);
    const pfx_seen = new Array(256).fill(0);
    let key;

    /* NO_SIGNAL is not defined: ^C is claimed before anything else. */
    keys_used[0x03 /* C('c') */] = true;

    /* movement keys have been flagged in keys_used[]; clone them */
    const mov_seen = keys_used.slice();

    const num_pad = !!(g.Cmd && g.Cmd.num_pad);
    let spkey_gap = false;
    for (const mk of MISC_KEYS) {
        if (mk.numpad && !num_pad)
            continue;
        const j = mk.nhkf;
        key = spkey_of(j);
        if (key && !mov_seen[key] && !pfx_seen[key]) {
            keys_used[key] = true;
            pfx_seen[key] = j;
        } else {
            spkey_gap = true;
        }
    }

    const datawin = [];
    datawin.push('');
    datawin.push(`${_pad_r('', 7)} ${'    Full Current Key Bindings List'}`);
    for (const extcmd of EXTCMDLIST)
        if (spkey_gap || !keylist_func_has_key(extcmd, keys_used)) {
            datawin.push(`${_pad_r('', 7)} ${'(also commands with no key assignment)'}`);
            break;
        }

    /* directional keys */
    datawin.push('');
    datawin.push('Directional keys:');
    for (const ln of show_direction_keys('.', false))  /* '.'==self in direct'n grid */
        datawin.push(ln);

    let buf;
    if (!num_pad) {
        datawin.push('');
        datawin.push('Ctrl+<direction> will run in specified direction until something very');
        datawin.push(`${_pad_r('', 7)} ${'interesting is seen.'}`);
        buf = 'Shift';   /* append the rest below */
    } else {
        datawin.push('');
        buf = 'Meta';
    }
    buf += '+<direction> will run in specified direction until you encounter';
    datawin.push(buf);
    datawin.push(`${_pad_r('', 7)} ${'an obstacle.'}`);

    datawin.push('');
    datawin.push('Miscellaneous keys:');
    for (const mk of MISC_KEYS) {
        if (mk.numpad && !num_pad)
            continue;
        const j = mk.nhkf;
        key = spkey_of(j);
        if (key && !mov_seen[key] && pfx_seen[key] === j)
            datawin.push(`${_pad_l(key2txt(key), 7)} ${mk.desc}`);
    }
    /* last of the special keys (NO_SIGNAL undefined) */
    key = 0x03; /* C('c') */
    datawin.push(`${_pad_l(key2txt(key), 7)} interrupt: break out of NetHack (SIGINT)`);
    /* keyless special key commands, if any */
    if (spkey_gap) {
        for (const mk of MISC_KEYS) {
            if (mk.numpad && !num_pad)
                continue;
            const j = mk.nhkf;
            key = spkey_of(j);
            if (!key || pfx_seen[key] !== j) {
                /* lines up with the other unassigned commands which use
                 * "#%-20s ", but not with the other special keys */
                datawin.push(`${_pad_l(`[${spkey_name(j)}]`, 21)} ${mk.desc}`);
            }
        }
    }

    const IGNORECMD = WIZMODECMD | INTERNALCMD | MOVEMENTCMD;

    datawin.push('');
    for (const ln of show_menu_controls(true))
        datawin.push(ln);

    if (keylist_putcmds(datawin, true, GENERALCMD, IGNORECMD, keys_used)) {
        datawin.push('');
        datawin.push('General commands:');
        keylist_putcmds(datawin, false, GENERALCMD, IGNORECMD, keys_used);
    }
    if (keylist_putcmds(datawin, true, 0, GENERALCMD | IGNORECMD, keys_used)) {
        datawin.push('');
        datawin.push('Game commands:');
        keylist_putcmds(datawin, false, 0, GENERALCMD | IGNORECMD, keys_used);
    }
    if (wizard() && keylist_putcmds(datawin, true, WIZMODECMD, INTERNALCMD, keys_used)) {
        datawin.push('');
        datawin.push('Debug mode commands:');
        keylist_putcmds(datawin, false, WIZMODECMD, INTERNALCMD, keys_used);
    }

    await display_text_window(datawin);
}

const GENERALCMD = 0x0008;
